import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.BKVF-9lJ.js";const l=JSON.parse('{"title":"Packages","description":"","frontmatter":{},"headers":[],"relativePath":"packages/index.md","filePath":"packages/index.md","lastUpdated":1791840224000}'),d={name:"packages/index.md"};function c(s,e,n,i,h,g){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h1><p>MFE Forge ships one CLI and five runtime/tooling packages. All are versioned together, are ESM-only, require Node.js 20 or later, and are released under the MIT license.</p><div class="warning custom-block"><p class="custom-block-title">Pre-1.0</p><p>Every package is on the <code>0.x</code> line. APIs may change between minor versions; pin versions and read the changelog when upgrading.</p></div><table tabindex="0"><thead><tr><th>Package</th><th>Version</th><th>Purpose</th><th>Peer dependencies</th></tr></thead><tbody><tr><td><a href="./../cli/"><code>mfe-forge</code></a></td><td>0.1.1</td><td>CLI for scaffolding and managing the workspace</td><td>none</td></tr><tr><td><a href="./core"><code>@mfe-forge/core</code></a></td><td>0.1.1</td><td>Error boundaries, event bus, remote loading, remote registry</td><td><code>react@^19</code>, <code>react-dom@^19</code></td></tr><tr><td><a href="./router"><code>@mfe-forge/router</code></a></td><td>0.1.1</td><td>Cross-scope navigation, route events, route generation, guards</td><td><code>react@^19</code>, <code>react-dom@^19</code>, <code>react-router-dom@^7</code></td></tr><tr><td><a href="./store"><code>@mfe-forge/store</code></a></td><td>0.1.1</td><td>Global and scoped Zustand stores, event-bus sync</td><td><code>zustand@^5</code></td></tr><tr><td><a href="./design"><code>@mfe-forge/design</code></a></td><td>0.1.1</td><td>Shared design tokens as a typed object and CSS custom properties</td><td>see package page</td></tr><tr><td><a href="./testing"><code>@mfe-forge/testing</code></a></td><td>0.1.1</td><td>Vitest, Testing Library and Playwright helpers</td><td>see package page</td></tr></tbody></table><h2 id="mfe-forge-cli" tabindex="-1">mfe-forge (CLI) <a class="header-anchor" href="#mfe-forge-cli" aria-label="Permalink to &quot;mfe-forge (CLI)&quot;">​</a></h2><p>The <code>mfe-forge</code> command scaffolds a workspace (<code>init</code>), generates scoped hosts and remotes (<code>generate host|app</code>), discovers the project topology and keeps each host&#39;s federation remotes and type declarations in sync (<code>sync</code>). It is the only package you run rather than import. See the <a href="./../cli/">CLI reference</a> and <a href="./../config">configuration</a>.</p><h2 id="mfe-forge-core" tabindex="-1">@mfe-forge/core <a class="header-anchor" href="#mfe-forge-core" aria-label="Permalink to &quot;@mfe-forge/core&quot;">​</a></h2><p>The runtime foundation every host and remote can share. <code>MFErrorBoundary</code> isolates a failing remote behind an accessible fallback with a working &quot;Try again&quot;; <code>RemoteLoader</code> and <code>LazyRemote</code> wrap a remote in <code>Suspense</code> plus that boundary and perform a real retry; <code>EventBus</code> / <code>globalEventBus</code> provide prefix-namespaced publish/subscribe between MFEs; <code>RemoteRegistry</code> stores remote definitions and health metadata. See <a href="./core">core reference</a>.</p><h2 id="mfe-forge-router" tabindex="-1">@mfe-forge/router <a class="header-anchor" href="#mfe-forge-router" aria-label="Permalink to &quot;@mfe-forge/router&quot;">​</a></h2><p>Thin helpers on top of React Router 7: <code>useMFENavigation</code> navigates to <code>/&lt;scope&gt;/&lt;path&gt;</code> with slash normalization and reports the current scope, <code>useRouteSync</code> broadcasts <code>route:changed</code> events over an event bus, <code>generateRoutes</code> turns a scope-to-routes registry into <code>&lt;Route&gt;</code> elements, and <code>createRouteGuard</code> builds a sync-or-async access guard. See <a href="./router">router reference</a>.</p><h2 id="mfe-forge-store" tabindex="-1">@mfe-forge/store <a class="header-anchor" href="#mfe-forge-store" aria-label="Permalink to &quot;@mfe-forge/store&quot;">​</a></h2><p>Shared state built on Zustand 5. <code>useGlobalStore</code> holds cross-cutting state (user, theme, locale, feature flags); <code>createScopedStore</code> creates an independent per-MFE store with a <code>reset()</code> action; <code>syncStoreAcrossMFEs</code> emits <code>&lt;prefix&gt;:sync</code> events carrying the new state and an origin id. See <a href="./store">store reference</a>.</p><h2 id="mfe-forge-design" tabindex="-1">@mfe-forge/design <a class="header-anchor" href="#mfe-forge-design" aria-label="Permalink to &quot;@mfe-forge/design&quot;">​</a></h2><p>Shared design tokens (<code>colors</code>, <code>radius</code>, <code>font</code>, <code>spacing</code>) exposed as a typed <code>tokens</code> object and applied to the DOM as CSS custom properties with <code>applyTokens()</code>. See <a href="./design">design reference</a>.</p><h2 id="mfe-forge-testing" tabindex="-1">@mfe-forge/testing <a class="header-anchor" href="#mfe-forge-testing" aria-label="Permalink to &quot;@mfe-forge/testing&quot;">​</a></h2><p>Test helpers for MFE Forge projects: <code>renderMFE</code> renders a component with a route, initial state and wrapper inside <code>React.StrictMode</code>, plus utilities for mocking remote modules and Playwright end-to-end checks that rely on the <code>data-testid</code> hooks emitted by <code>@mfe-forge/core</code>. Install it as a dev dependency. See <a href="./testing">testing reference</a>.</p><h2 id="sharing-runtime-packages" tabindex="-1">Sharing runtime packages <a class="header-anchor" href="#sharing-runtime-packages" aria-label="Permalink to &quot;Sharing runtime packages&quot;">​</a></h2><p>When remotes are built separately, share <code>react</code>, <code>react-dom</code>, <code>react-router-dom</code>, <code>zustand</code> and the <code>@mfe-forge/*</code> runtime packages as Module Federation singletons. Otherwise each bundle gets its own <code>globalEventBus</code>, <code>useGlobalStore</code> and remote cache, and cross-MFE communication silently stops working. See <a href="./../architecture">architecture</a> and <a href="./../troubleshooting">troubleshooting</a>.</p>',18)])])}const p=o(d,[["render",c]]);export{l as __pageData,p as default};
